INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 44, "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 2, 8, 16, 155, "獣人族", 100101, 0, "人助け、応援", "東山奈央", "ヒヨリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 47, "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 2, 4, 17, 158, "ヒューマン", 100201, 0, "料理、人間観察", "種田梨沙", "ユイ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 46, "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 2, 1, 18, 163, "魔族", 100301, 0, "読書、乗馬、お茶", "早見沙織", "レイ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 10, 27, "リトルリリカル", "探検好きのイタズラっ子", 5, 8, 9, 128, "ヒューマン", 100401, 0, "いたずら、探検", "諸星すみれ", "ミソギ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "？？？", 25, 40, "王宮騎士団（NIGHTMARE）", "ヒーローに憧れる騎士見習いの少女", 8, 11, 12, 146, "獣人族", 100501, 0, "ヒーローごっこ", "下田麻美", "マツリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 22, 42, "悪魔偽王国軍（ディアボロス）", "甘え上手なみんなの人気者", 7, 11, 13, 150, "魔族", 100601, 0, "サックス", "浅倉杏美", "アカリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 23, 32, "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", 7, 1, 14, 130, "魔族", 100701, 0, "プリンを食べること", "雨宮天", "ミヤコ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 10, 40, "ヴァイスフリューゲル　ランドソル支部", "ボクは誰よりも美しい", 15, 10, 14, 150, "エルフ", 100801, 0, "鏡で自分を見ること", "大空直美", "ユキ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 5, 45, "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", 13, 7, 17, 159, "魔族", 100901, 0, "小説執筆", "髙野麻美", "アンナ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 22, 42, "自警団（カォン）", "マホマホ王国のプリンセス", 10, 9, 16, 155, "獣人族", 101001, 0, "空想、ぬいぐるみ集め", "内田真礼", "マホ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 25, 44, "ラビリンス", "人懐っこくてマシンガントークな妹系少女", 3, 8, 15, 156, "ヒューマン", 101101, 0, "お裁縫", "阿澄佳奈", "リノ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 24, 46, "フォレスティエ", "みんなのために超能力を使う眠り姫", 6, 12, 17, 156, "エルフ", 101201, 0, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香", "ハツネ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "", 21, 55, "トワイライトキャラバン", "オタク全開な魔法少女", 13, 8, 18, 166, "魔族", 101301, 0, "読書、魔法", "佳村はるか", "ナナカ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "test", 3, 41, "自警団（カォン）", "頭脳明晰な美少女名探偵", 10, 11, 15, 152, "獣人族", 101401, 0, "読書、推理", "水瀬いのり", "カスミ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "test", 5, 54, "フォレスティエ", "母性溢れる優しいみんなの「ミサト先生」", 6, 9, 21, 165, "エルフ", 101501, 0, "絵本作り", "國府田マリ子", "ミサト");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 10, 48, "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 14, 4, 17, 167, "魔族", 101601, 0, "ファッション", "上坂すみれ", "スズナ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 7, 53, "自警団（カォン）", "いつでも「なんくるないさ～」な天然娘", 10, 7, 17, 158, "獣人族", 101701, 0, "踊り、空手", "高森奈津美", "カオリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 14, 52, "ルーセント学院", "多くの男性を魅了する無垢な女教師", 14, 8, 23, 162, "魔族", 101801, 0, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静", "イオ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 3, 21, "リトルリリカル", "お歌もにんじんも、ウサギさんも大好き♪", 5, 4, 10, 117, "獣人族", 102001, 0, "かわいいもの集め", "日高里菜", "ミミ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 9, 40, "サレンディア救護院", "泣き虫で臆病な守ってあげたい女の子", 9, 6, 12, 150, "ヒューマン", 102101, 0, "観劇、おままごと", "植田佳奈", "クルミ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 22, 40, "悪魔偽王国軍（ディアボロス）", "人見知りであまのじゃくな女の子", 7, 11, 13, 150, "魔族", 102201, 0, "ゲーム全般", "原紗友里", "ヨリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 10, 38, "サレンディア救護院", "ぷうきちといつも一緒！", 9, 5, 14, 148, "ヒューマン", 102301, 0, "屋内でできる遊び", "芹澤優", "アヤネ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 12, 43, "サレンディア救護院", "お嬢さまのためにがんばるドジっ娘メイド", 9, 12, 15, 154, "ヒューマン", 102501, 0, "ご奉仕", "悠木碧", "スズメ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "test", 1, 42, "牧場（エリザベスパーク）", "遊びと睡眠が何より大事なぐうたら娘", 11, 1, 17, 144, "獣人族", 102601, 0, "あんパン", "小岩井ことり", "リン");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 30, 43, "トワイライトキャラバン", "運命の相手に一途すぎる乙女", 13, 7, 16, 154, "魔族", 102701, 0, "実験、裁縫、料理", "橋本ちなみ", "エリコ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 4, 43, "サレンディア救護院", "救護院を経営する優しい庶民派お嬢様", 9, 10, 17, 156, "エルフ", 102801, 0, "経営、お茶会", "堀江由衣", "サレン");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 24, 40, "カルミナ", "歌って踊れる大人気アイドル", 4, 1, 17, 157, "ヒューマン", 102901, 0, "舞台鑑賞、ダンス", "日笠陽子", "ノゾミ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 31, 51, "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", 15, 8, 16, 163, "ヒューマン", 103001, 0, "忍法開発", "佐藤聡美", "ニノン");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 22, 42, "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 7, 12, 18, 157, "魔族", 103101, 0, "占い", "大坪由佳", "シノブ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 12, 45, "メルクリウス財団", "一人前の商人を目指すパワフルお嬢様", 12, 3, 18, 157, "ヒューマン", 103201, 0, "慈善事業", "松嵜麗", "アキノ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 3, 35, "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", 11, 3, 20, 142, "ヒューマン", 103301, 0, "漫才", "新田恵海", "マヒル");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 16, 55, "メルクリウス財団", "純情でほっとけない大人の女性", 12, 3, 22, 164, "エルフ", 103401, 0, "ウインドーショッピング", "今井麻美", "ユカリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "test", 2, 21, "リトルリリカル", "礼儀正しくしっかり者のちびっ子優等生", 5, 2, 8, 118, "エルフ", 103601, 0, "お勉強", "小倉唯", "キョウカ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "test", 11, 43, "王宮騎士団（NIGHTMARE）", "義理堅くてからかい好きな剣術少女", 8, 8, 13, 149, "ヒューマン", 103701, 0, "剣術、年長者をからかう", "茅原実里", "トモ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 3, 40, "牧場（エリザベスパーク）", "読書が趣味の病弱少女", 11, 11, 14, 153, "獣人族", 103801, 0, "読書、お散歩", "小清水亜美", "シオリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 6, 44, "フォレスティエ", "「友達」に憧れる、エルフの森の女の子", 6, 6, 13, 158, "エルフ", 104001, 0, "友達作りのイメトレ", "花澤香菜", "アオイ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 3, 46, "カルミナ", "人々を守るために歌う、唱喚士の少女", 4, 6, 17, 163, "ヒューマン", 104201, 0, "各種楽器", "福原綾香", "チカ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 9, 54, "自警団（カォン）", "男勝りで情に厚いワイルド娘", 10, 8, 17, 168, "獣人族", 104301, 0, "お菓子作り", "小松未可子", "マコト");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "test", 5, 50, "悪魔偽王国軍（ディアボロス）", "かつては夜を支配した最強の吸血鬼", 7, 5, "??", 172, "魔族", 104401, 0, "世界征服", "丹下桜", "イリヤ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 19, 49, "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 15, 11, 18, 157, "ヒューマン", 104501, 0, "小説を読むこと", "長妻樹里", "クウカ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 1, 48, "メルクリウス財団", "弱きを助け強きをくじく猫娘", 12, 3, 19, 158, "獣人族", 104601, 0, "猫とたわむれること", "沼倉愛美", "タマキ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "？？？", 25, 50, "王宮騎士団（NIGHTMARE）", "素顔を見せない冷静沈着な女性騎士", 8, 10, 25, 171, "ヒューマン", 104701, 0, "格闘技、湯浴み", "川澄綾子", "ジュン");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 11, 49, "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", 12, 11, 20, 163, "ヒューマン", 104801, 0, "傭兵などのアルバイト", "田所あずさ", "ミフユ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 24, 54, "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", 3, 10, 18, 168, "ヒューマン", 104901, 0, "家事全般", "生天目仁美", "シズル");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 3, 22, "ルーセント学院", "ちょっとおませな恋に恋する女の子", 14, 1, 11, 120, "魔族", 105001, 0, "ファッション誌鑑賞、コスメ集め", "久野美咲", "ミサキ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 7, 53, "トワイライトキャラバン", "実験が趣味の危険な科学者", 13, 3, 27, 166, "ヒューマン", 105101, 0, "研究、実験", "三石琴乃", "ミツキ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 14, 100, "牧場（エリザベスパーク）", "乙女チックなもふもふアニマル", 11, 3, 17, 150, "獣人族", 105201, 0, "毛繕い、お喋り", "徳井青空", "リマ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 28, 33, "ヴァイスフリューゲル　ランドソル支部", "見た目も中身もお子ちゃまな異国の軍人", 15, 7, 17, 140, "ヒューマン", 105301, 0, "お菓子屋通い", "辻あゆみ", "モニカ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "test", 7, 45, "カルミナ", "ファッション大好きなキュートガール", 4, 9, 14, 153, "ヒューマン", 105401, 0, "裁縫", "木戸衣吹", "ツムギ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "test", 7, 43, "ヴァイスフリューゲル　ランドソル支部", "どこまでも一途に慕う、純情乙女", 15, 4, 16, 155, "エルフ", 105501, 0, "観察", "大関英里", "アユミ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "test", 11, 54, "トワイライトキャラバン", "人情味溢れる粋でいなせな「姉御」", 13, 7, 25, 167, "ヒューマン", 105601, 0, "釣り", "佐藤利奈", "ルカ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 10, 45, "？？？", "空への冒険を夢見る騎空士の少女", "", 3, 17, 156, "ヒューマン", 105701, 0, "冒険、おしゃべり", "金元寿子", "ジータ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 31, 46, "美食殿", "いつも元気な腹ペコ少女", 1, 3, 17, 156, "ヒューマン", 105801, 0, "食べ歩き、料理", "M・A・O", "ペコリーヌ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 11, 35, "美食殿", "主を慕う、小さなガイド役", 1, 5, 11, 140, "エルフ", 105901, 0, "瞑想、動植物の飼育", "伊藤美来", "コッコロ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 2, 39, "美食殿", "行き倒れの謎のネコミミ魔法使い", 1, 9, 14, 152, "獣人族", 106001, 0, "猫と遊ぶ", "立花理香", "キャル");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 11, 40, "？？？", "さまよえる謎の少女", "", 8, 16, 148, "ヒューマン", 106101, 0, "冒険、思い出話", "潘めぐみ", "ムイミ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "", 17, 42, "？？？", "森番を目指すエルフの少女", "", 6, 15, 155, "エルフ", 106301, 0, "キレイな葉っぱを集めること", "優木かな", "アリサ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "", 14, "???", "美食殿", "記憶喪失のドラゴン娘", 1, 12, 14, 147, "ドラゴン族", 106401, 0, "読書、ストレッチ", "近藤玲奈", "シェフィ");
