INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 29, "???", "ドラゴンズネスト", "口が達者なヘタレドラゴン", 17, 9, 13, 145, "ドラゴン族", 106601, 0, "ゲーム", "藤田茜", "イノリ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "", 17, "???", "ドラゴンズネスト", "妖しい微笑で全てを見透かす臥竜の頭領", 17, 4, 25, 168, "ドラゴン族", 106701, 0, "絵画、読書", "大西沙織", "ホマレ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 25, "??", "ラビリンス", "秘密結社ラビリンスの『迷宮女王』", 3, 7, 25, 160, "ヒューマン", 106801, 0, "人間観察", "沢城みゆき", "ラビリスタ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 1, "??", "？？？", "謎に包まれたランドソルの主", "", 7, 29, 166, "獣人族", 106901, 0, "占い、支配", "蒼井翔太", "カイザーインサイト");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "", 24, "??", "？？？", "研究所に隠れ住む物静かなお姉さん", "", 3, 24, 149, "エルフ", 107001, 0, "物真似、芸術鑑賞", "井口裕香", "ネネカ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "", 7, "??", "王宮騎士団（NIGHTMARE）", "傍若無人な王宮騎士団副団長", 8, 2, 27, 165, "ヒューマン", 107101, 0, "強敵との闘争", "たかはし智秋", "クリスティーナ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 31, 46, "美食殿", "いつも元気な腹ペコ少女", 1, 3, 17, 156, "ヒューマン", 107501, 0, "食べ歩き、料理", "M・A・O", "ペコリーヌ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 11, 35, "美食殿", "主を慕う、小さなガイド役", 1, 5, 11, 140, "エルフ", 107601, 0, "瞑想、動植物の飼育", "伊藤美来", "コッコロ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 12, 43, "サレンディア救護院", "お嬢さまのためにがんばるドジっ娘メイド", 9, 12, 15, 154, "ヒューマン", 107701, 0, "ご奉仕", "悠木碧", "スズメ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 2, 39, "美食殿", "行き倒れの謎のネコミミ魔法使い", 1, 9, 14, 152, "獣人族", 107801, 0, "猫と遊ぶ", "立花理香", "キャル（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 1, 48, "メルクリウス財団", "弱きを助け強きをくじく猫娘", 12, 3, 19, 158, "獣人族", 107901, 0, "猫とたわむれること", "沼倉愛美", "タマキ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 11, 49, "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", 12, 11, 20, 163, "ヒューマン", 108001, 0, "傭兵などのアルバイト", "田所あずさ", "ミフユ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 22, 42, "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 7, 12, 18, 157, "魔族", 108101, 0, "占い", "大坪由佳", "シノブ（ハロウィン）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 23, 32, "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", 7, 1, 14, 130, "魔族", 108201, 0, "プリンを食べること", "雨宮天", "ミヤコ（ハロウィン）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 3, 22, "ルーセント学院", "ちょっとおませな恋に恋する女の子", 14, 1, 11, 120, "魔族", 108301, 0, "ファッション誌鑑賞、コスメ集め", "久野美咲", "ミサキ（ハロウィン）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 3, 46, "カルミナ", "人々を守るために歌う、唱喚士の少女", 4, 6, 17, 163, "ヒューマン", 108401, 0, "各種楽器", "福原綾香", "チカ（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 9, 40, "サレンディア救護院", "泣き虫で臆病な守ってあげたい女の子", 9, 6, 12, 150, "ヒューマン", 108501, 0, "観劇、おままごと", "植田佳奈", "クルミ（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 10, 38, "サレンディア救護院", "ぷうきちといつも一緒！", 9, 5, 14, 148, "ヒューマン", 108601, 0, "屋内でできる遊び", "芹澤優", "アヤネ（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 44, "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 2, 8, 16, 155, "獣人族", 108701, 0, "人助け、応援", "東山奈央", "ヒヨリ（ニューイヤー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 47, "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 2, 4, 17, 158, "ヒューマン", 108801, 0, "料理、人間観察", "種田梨沙", "ユイ（ニューイヤー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 46, "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 2, 1, 18, 163, "魔族", 108901, 0, "読書、乗馬、お茶", "早見沙織", "レイ（ニューイヤー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 30, 43, "トワイライトキャラバン", "運命の相手に一途すぎる乙女", 13, 7, 16, 154, "魔族", 109001, 0, "実験、裁縫、料理", "橋本ちなみ", "エリコ（バレンタイン）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 24, 54, "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", 3, 10, 18, 168, "ヒューマン", 109101, 0, "家事全般", "生天目仁美", "シズル（バレンタイン）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 1, 55, "？？？", "英霊と契約を結んだマナリアの天才王女", "", 12, 17, 156, "ヒューマン", 109201, 0, "読書", "日笠陽子", "アン");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 4, 45, "？？？", "マナリア魔法学院の新入生", "", 2, 16, 144, "ヒューマン", 109301, 0, "食べること、眠ること", "こやまきみこ", "ルゥ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 3, 67, "？？？", "人を超越した力を有す心優しい竜姫", "", 11, 17, 167, "半人半竜", 109401, 0, "ピアノ", "福原綾香", "グレア");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 19, 49, "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 15, 11, 18, 157, "ヒューマン", 109501, 0, "小説を読むこと", "長妻樹里", "クウカ（オーエド）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 31, 51, "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", 15, 8, 16, 163, "ヒューマン", 109601, 0, "忍法開発", "佐藤聡美", "ニノン（オーエド）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("?", "", 2, "??", "？？？", "鬼がかりの万能妹メイド", "", 2, 17, 154, "鬼族", 109701, 0, "演劇鑑賞、詩文", "水瀬いのり", "レム");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("?", "", 2, "??", "？？？", "毒舌系鬼姉メイド", "", 2, 17, 154, "鬼族", 109801, 0, "読書", "村川梨衣", "ラム");
