INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 10, 48, "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 14, 4, 17, 167, "魔族", 110001, 0, "ファッション", "上坂すみれ", "スズナ（サマー）");
