INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 3, 40, "牧場（エリザベスパーク）", "読書が趣味の病弱少女", 11, 11, 14, 153, "獣人族", 112301, 0, "読書、お散歩", "小清水亜美", "シオリ（マジカル）");
