INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 3, 35, "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", 11, 3, 20, 142, "ヒューマン", 112801, 0, "漫才", "新田恵海", "マヒル（レンジャー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 25, 44, "ラビリンス", "人懐っこくてマシンガントークな妹系少女", 3, 8, 15, 156, "ヒューマン", 112901, 0, "お裁縫", "阿澄佳奈", "リノ（ワンダー）");
