INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 5, 45, "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", 13, 7, 17, 159, "魔族", 113201, 0, "小説執筆", "髙野麻美", "アンナ（サマー）");
