INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 24, 46, "フォレスティエ", "みんなのために超能力を使う眠り姫", 6, 12, 17, 156, "エルフ", 113401, 0, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香", "ハツネ（サマー）");
