INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "", 25, 50, "王宮騎士団（NIGHTMARE）", "素顔を見せない冷静沈着な女性騎士", 8, 10, 25, 171, "ヒューマン", 113601, 0, "格闘技、湯浴み", "川澄綾子", "ジュン（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 22, 42, "悪魔偽王国軍（ディアボロス）", "甘え上手なみんなの人気者", 7, 11, 13, 150, "魔族", 113701, 0, "サックス", "浅倉杏美", "アカリ（エンジェル）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 22, 40, "悪魔偽王国軍（ディアボロス）", "人見知りであまのじゃくな女の子", 7, 11, 13, 150, "魔族", 113801, 0, "ゲーム全般", "原紗友里", "ヨリ（エンジェル）");
