INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 46, "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 2, 1, 18, 163, "魔族", 114001, 0, "読書、乗馬、お茶", "早見沙織", "レイ（ハロウィン）");
