INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！", 12, 45, "メルクリウス財団", "一人前の商人を目指すパワフルお嬢様", 12, 3, 18, 157, "ヒューマン", 114401, 0, "慈善事業", "松嵜麗", "アキノ（クリスマス）");
