INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 16, 55, "メルクリウス財団", "純情でほっとけない大人の女性", 12, 3, 22, 164, "エルフ", 114601, 0, "ウインドーショッピング", "今井麻美", "ユカリ（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 11, 40, "？？？", "さまよえる謎の少女", "", 8, 16, 148, "ヒューマン", 114701, 0, "冒険、思い出話", "潘めぐみ", "ムイミ（ニューイヤー）");
