INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 11, 35, "美食殿", "主を慕う、小さなガイド役", 1, 5, 11, 140, "エルフ", 115501, 0, "瞑想、動植物の飼育", "伊藤美来", "コッコロ（儀装束）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 47, "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 2, 4, 17, 158, "ヒューマン", 115601, 0, "料理、人間観察", "種田梨沙", "ユイ（儀装束）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 3, 41, "自警団（カォン）", "頭脳明晰な美少女名探偵", 10, 11, 15, 152, "獣人族", 115701, 0, "読書、推理", "水瀬いのり", "カスミ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 14, 100, "牧場（エリザベスパーク）", "乙女チックなもふもふアニマル", 11, 3, 17, 150, "獣人族", 115801, 0, "毛繕い、お喋り", "徳井青空", "リマ（シンデレラ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 9, 54, "自警団（カォン）", "男勝りで情に厚いワイルド娘", 10, 8, 17, 168, "獣人族", 115901, 0, "お菓子作り", "小松未可子", "マコト（シンデレラ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 22, 42, "自警団（カォン）", "マホマホ王国のプリンセス", 10, 9, 16, 155, "獣人族", 116001, 0, "空想、ぬいぐるみ集め", "内田真礼", "マホ（シンデレラ）");
