INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 6, 44, "フォレスティエ", "「友達」に憧れる、エルフの森の女の子", 6, 6, 13, 158, "エルフ", 116701, 0, "友達作りのイメトレ", "花澤香菜", "アオイ（作業服）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 1, 48, "メルクリウス財団", "弱きを助け強きをくじく猫娘", 12, 3, 19, 158, "獣人族", 116801, 0, "猫とたわむれること", "沼倉愛美", "タマキ（作業服）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 11, 49, "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", 12, 11, 20, 163, "ヒューマン", 116901, 0, "傭兵などのアルバイト", "田所あずさ", "ミフユ（作業服）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 30, 43, "トワイライトキャラバン", "運命の相手に一途すぎる乙女", 13, 7, 16, 154, "魔族", 117001, 0, "実験、裁縫、料理", "橋本ちなみ", "エリコ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 24, 54, "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", 3, 10, 18, 168, "ヒューマン", 117101, 0, "家事全般", "生天目仁美", "シズル（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "", 24, 40, "カルミナ", "歌って踊れる大人気アイドル", 4, 1, 17, 157, "ヒューマン", 117201, 0, "舞台鑑賞、ダンス", "日笠陽子", "ノゾミ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 3, 46, "カルミナ", "人々を守るために歌う、唱喚士の少女", 4, 6, 17, 163, "ヒューマン", 117301, 0, "各種楽器", "福原綾香", "チカ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 7, 45, "カルミナ", "ファッション大好きなキュートガール", 4, 9, 14, 153, "ヒューマン", 117401, 0, "裁縫", "木戸衣吹", "ツムギ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 7, 53, "トワイライトキャラバン", "実験が趣味の危険な科学者", 13, 3, 27, 166, "ヒューマン", 117501, 0, "研究、実験", "三石琴乃", "ミツキ（オーエド）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 10, 40, "ヴァイスフリューゲル　ランドソル支部", "ボクは誰よりも美しい", 15, 10, 14, 150, "エルフ", 117601, 0, "鏡で自分を見ること", "大空直美", "ユキ（オーエド）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 7, 53, "自警団（カォン）", "いつでも「なんくるないさ～」な天然娘", 10, 7, 17, 158, "獣人族", 117701, 0, "踊り、空手", "高森奈津美", "カオリ（ハロウィン）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 31, 51, "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", 15, 8, 16, 163, "ヒューマン", 117801, 0, "忍法開発", "佐藤聡美", "ニノン（ハロウィン）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 10, 48, "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 14, 4, 17, 167, "魔族", 117901, 0, "ファッション", "上坂すみれ", "スズナ（ハロウィン）");
