INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 14, 52, "ルーセント学院", "多くの男性を魅了する無垢な女教師", 14, 8, 23, 162, "魔族", 119001, 0, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静", "イオ（ノワール）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 19, 49, "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 15, 11, 18, 157, "ヒューマン", 119101, 0, "小説を読むこと", "長妻樹里", "クウカ（ノワール）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 3, 35, "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", 11, 3, 20, 142, "ヒューマン", 119201, 0, "漫才", "新田恵海", "マヒル（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 25, 44, "ラビリンス", "人懐っこくてマシンガントークな妹系少女", 3, 8, 15, 156, "ヒューマン", 119301, 0, "お裁縫", "阿澄佳奈", "リノ（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 23, 32, "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", 7, 1, 14, 130, "魔族", 119901, 0, "プリンを食べること", "雨宮天", "ミヤコ（クリスマス）");
