INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 5, 45, "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", 13, 7, 17, 159, "魔族", 121901, 0, "小説執筆", "髙野麻美", "アンナ（パイレーツ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 22, 42, "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 7, 12, 18, 157, "魔族", 122001, 0, "占い", "大坪由佳", "シノブ（パイレーツ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 6, 44, "フォレスティエ", "「友達」に憧れる、エルフの森の女の子", 6, 6, 13, 158, "エルフ", 122101, 0, "友達作りのイメトレ", "花澤香菜", "アオイ（キャンプ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 16, 55, "メルクリウス財団", "純情でほっとけない大人の女性", 12, 3, 22, 164, "エルフ", 122201, 0, "ウインドーショッピング", "今井麻美", "ユカリ（キャンプ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 6, 41, "？？？", "けんぞくのご主人様", "", 12, "??", 149, "魔族", 122301, 0, "お散歩、お料理", "釘宮理恵", "ヴァンピィ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 44, "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 2, 8, 16, 155, "獣人族", 122401, 0, "人助け、応援", "東山奈央", "ヒヨリ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 46, "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 2, 1, 18, 163, "魔族", 122501, 0, "読書、乗馬、お茶", "早見沙織", "レイ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 47, "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 2, 4, 17, 158, "ヒューマン", 122601, 0, "料理、人間観察", "種田梨沙", "ユイ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "", 2, 21, "リトルリリカル", "礼儀正しくしっかり者のちびっ子優等生", 5, 2, 8, 118, "エルフ", 122701, 0, "お勉強", "小倉唯", "キョウカ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 10, 27, "リトルリリカル", "探検好きのイタズラっ子", 5, 8, 9, 128, "ヒューマン", 122801, 0, "いたずら、探検", "諸星すみれ", "ミソギ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 3, 21, "リトルリリカル", "お歌もにんじんも、ウサギさんも大好き♪", 5, 4, 10, 117, "獣人族", 122901, 0, "かわいいもの集め", "日高里菜", "ミミ（サマー）");
