INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 22, 42, "自警団（カォン）", "マホマホ王国のプリンセス", 10, 9, 16, 155, "獣人族", 123101, 0, "空想、ぬいぐるみ集め", "内田真礼", "マホ（エクスプローラー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 10, 38, "サレンディア救護院", "ぷうきちといつも一緒！", 9, 5, 14, 148, "ヒューマン", 123201, 0, "屋内でできる遊び", "芹澤優", "アヤネ（エクスプローラー）");
