INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 22, 42, "悪魔偽王国軍（ディアボロス）", "甘え上手なみんなの人気者", 7, 11, 13, 150, "魔族", 124001, 0, "サックス", "浅倉杏美", "アカリ（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 22, 40, "悪魔偽王国軍（ディアボロス）", "人見知りであまのじゃくな女の子", 7, 11, 13, 150, "魔族", 124101, 0, "ゲーム全般", "原紗友里", "ヨリ（クリスマス）");
