INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 7, 53, "トワイライトキャラバン", "実験が趣味の危険な科学者", 13, 3, 27, 166, "ヒューマン", 124701, 0, "研究、実験", "三石琴乃", "ミツキ（ニューイヤー）");
