INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 11, 40, "？？？", "さまよえる謎の少女", "", 8, 16, 148, "ヒューマン", 125001, 0, "冒険、思い出話", "潘めぐみ", "ムイミ（リベレイター）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 1, 48, "メルクリウス財団", "弱きを助け強きをくじく猫娘", 12, 3, 19, 158, "獣人族", 125101, 0, "猫とたわむれること", "沼倉愛美", "タマキ（カフェ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 28, 33, "ヴァイスフリューゲル　ランドソル支部", "見た目も中身もお子ちゃまな異国の軍人", 15, 7, 17, 140, "ヒューマン", 125201, 0, "お菓子屋通い", "辻あゆみ", "モニカ（カフェ）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 11, 35, "美食殿", "主を慕う、小さなガイド役", 1, 5, 11, 140, "エルフ", 125301, 0, "瞑想、動植物の飼育", "伊藤美来", "コッコロ（レンジャー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 3, 40, "牧場（エリザベスパーク）", "読書が趣味の病弱少女", 11, 11, 14, 153, "獣人族", 125401, 0, "読書、お散歩", "小清水亜美", "シオリ（レンジャー）");
