INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "", 28, 53, "レイジ・レギオン", "静寂を求め歌う陰気少女", 19, 12, 20, 165, "魔族", 126901, 0, "歌、読書、詩を書くこと", "原田彩楓", "ランファ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 19, 49, "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 15, 11, 18, 157, "ヒューマン", 127001, 0, "小説を読むこと", "長妻樹里", "クウカ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 22, 42, "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 7, 12, 18, 157, "魔族", 127101, 0, "占い", "大坪由佳", "シノブ（サマー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 2, 39, "美食殿", "行き倒れの謎のネコミミ魔法使い", 1, 9, 14, 152, "獣人族", 127201, 0, "猫と遊ぶ", "立花理香", "キャル（編入生）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 10, 48, "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 14, 4, 17, 167, "魔族", 127301, 0, "ファッション", "上坂すみれ", "スズナ（編入生）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 4, 43, "サレンディア救護院", "救護院を経営する優しい庶民派お嬢様", 9, 10, 17, 156, "エルフ", 127501, 0, "経営、お茶会", "堀江由衣", "サレン（サラサリア）");
