INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 31, 46, "美食殿", "いつも元気な腹ペコ少女", 1, 3, 17, 156, "ヒューマン", 127901, 0, "食べ歩き、料理", "M・A・O", "ペコリーヌ（クリスマス）");
