INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 24, 46, "フォレスティエ", "みんなのために超能力を使う眠り姫", 6, 12, 17, 156, "エルフ", 128401, 0, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香", "ハツネ（ニューイヤー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "", 3, 41, "自警団（カォン）", "頭脳明晰な美少女名探偵", 10, 11, 15, 152, "獣人族", 128501, 0, "読書、推理", "水瀬いのり", "カスミ（ニューイヤー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 44, "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 2, 8, 16, 155, "獣人族", 128701, 0, "人助け、応援", "東山奈央", "ヒヨリ（アストラル）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 46, "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 2, 1, 18, 163, "魔族", 128801, 0, "読書、乗馬、お茶", "早見沙織", "レイ（アストラル）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 47, "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 2, 4, 17, 158, "ヒューマン", 128901, 0, "料理、人間観察", "種田梨沙", "ユイ（アストラル）");
