INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 47, "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 2, 4, 17, 158, "ヒューマン", 136401, 0, "料理、人間観察", "種田梨沙", "ユイ（クリスマス）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 24, 54, "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", 3, 10, 18, 168, "ヒューマン", 136501, 0, "家事全般", "生天目仁美", "シズル（ニューイヤー）");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("青", "", 8, "??", "？？？", "がんばりましゅ！　うじゅうじゅタコ娘", "", 10, "13(?)", 148, "？？？", 136901, 0, "タコ料理、潮干狩り、ひとりじゃんけん", "飯田ヒカル", "ルルィ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 31, 51, "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", 15, 8, 16, 163, "ヒューマン", 137101, 0, "忍法開発", "佐藤聡美", "ニノン（サマー）");
