INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 44, "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 2, 8, 16, 155, "獣人族", 180101, 0, "人助け、応援", "東山奈央", "ヒヨリ（プリンセス）");
